/** Astro `redirects` config: only URLs that actually move. */
export const redirects: Record<string, { status: 301 | 302 | 308; destination: string }> = Object.fromEntries(
  urlMap
    .filter((m): m is UrlMapping & { to: string; status: 301 | 302 | 308 } => m.to !== null && m.to !== m.from && m.status !== 410)
    .map((m) => [m.from, { status: m.status, destination: m.to }]),
);
